INSERT INTO calculus (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the limit of (x^2 - 4)/(x - 2) as x approaches 2?', '4', '2', '0', 'undefined', '4', 'Factor the numerator: (x^2 - 4) = (x-2)(x+2), cancel (x-2), giving x+2; at x=2 this equals 4.', 710, 'Calculus'),
('Which rule states d/dx[u*v] = u''*v + u*v''?', 'Product rule', 'Quotient rule', 'Chain rule', 'Power rule', 'Product rule', 'The product rule applies when differentiating a product of two functions: d/dx[u*v] = u''v + uv''.', 720, 'Calculus'),
('What is the derivative of f(x) = sin(x)?', 'cos(x)', '-cos(x)', '-sin(x)', 'tan(x)', 'cos(x)', 'The derivative of sin(x) is cos(x), a fundamental trigonometric differentiation result.', 725, 'Calculus'),
('Evaluate the indefinite integral: integral of x^4 dx', 'x^5/5 + C', 'x^4 + C', '4x^3 + C', 'x^5 + C', 'x^5/5 + C', 'The power rule for integration states integral of x^n dx = x^(n+1)/(n+1) + C; here n=4 gives x^5/5 + C.', 730, 'Calculus'),
('What is lim(x->inf) 1/x?', '0', '1', 'infinity', 'undefined', '0', 'As x grows without bound, 1/x decreases toward 0; the limit is 0.', 715, 'Calculus'),
('What is the derivative of f(x) = cos(x)?', '-sin(x)', 'sin(x)', '-cos(x)', 'tan(x)', '-sin(x)', 'The derivative of cos(x) is -sin(x), a standard result from the definition of the derivative.', 720, 'Calculus'),
('A function f is continuous at x = a if lim(x->a) f(x) equals what?', 'f(a)', '0', 'f''(a)', '1', 'f(a)', 'Continuity at x=a requires that the limit as x approaches a equals the function value f(a).', 740, 'Calculus'),
('Evaluate the definite integral: integral from 0 to 1 of 2x dx', '1', '2', '1/2', '0', '1', 'integral of 2x dx = x^2; evaluating from 0 to 1 gives 1^2 - 0^2 = 1.', 745, 'Calculus'),
('What is the derivative of f(x) = x^n using the power rule?', 'n*x^(n-1)', 'x^(n+1)/(n+1)', '(n-1)*x^n', 'n*x^n', 'n*x^(n-1)', 'The power rule states d/dx[x^n] = n*x^(n-1) for any real n.', 722, 'Calculus'),
('What is the Fundamental Theorem of Calculus Part 2?', 'integral from a to b of f(x) dx = F(b) - F(a)', 'd/dx[integral from a to x of f(t) dt] = f(x)', 'Every continuous function has an antiderivative', 'The derivative and integral are inverses', 'integral from a to b of f(x) dx = F(b) - F(a)', 'FTC Part 2 states that if F is any antiderivative of f, then the definite integral from a to b equals F(b) - F(a).', 820, 'Calculus'),
('Use u-substitution to evaluate integral of 2x*sqrt(x^2 + 1) dx', '(2/3)(x^2+1)^(3/2) + C', '(x^2+1)^(1/2) + C', 'x*(x^2+1)^(1/2) + C', '2*(x^2+1) + C', '(2/3)(x^2+1)^(3/2) + C', 'Let u = x^2+1, du = 2x dx; the integral becomes integral of sqrt(u) du = (2/3)u^(3/2) + C = (2/3)(x^2+1)^(3/2) + C.', 960, 'Calculus'),
('What is d/dx[ln(x)]?', '1/x', 'x', 'e^x', 'ln(x)/x', '1/x', 'The derivative of the natural logarithm is d/dx[ln(x)] = 1/x for x > 0.', 780, 'Calculus'),
('Apply the chain rule: what is d/dx[cos(3x)]?', '-3*sin(3x)', 'sin(3x)', '-sin(3x)', '3*cos(3x)', '-3*sin(3x)', 'Chain rule: d/dx[cos(u)] = -sin(u)*u''; with u=3x, u''=3, giving -sin(3x)*3 = -3*sin(3x).', 840, 'Calculus'),
('Evaluate lim(x->0) (tan x)/x', '1', '0', 'infinity', 'undefined', '1', 'Since tan(x)/x = (sin x/cos x)/x = (sin x/x)*(1/cos x), and both factors approach 1 as x->0, the limit is 1.', 870, 'Calculus'),
('What is the quotient rule: d/dx[u/v]?', '(u''*v - u*v'') / v^2', '(u*v'' - u''*v) / v^2', 'u''*v'' / v', '(u'' - v'') / v', '(u''*v - u*v'') / v^2', 'The quotient rule is d/dx[u/v] = (u''v - uv'')/v^2; remember "low d-high minus high d-low over low squared."', 810, 'Calculus'),
('Find the critical points of f(x) = x^3 - 3x by setting f''(x) = 0. What are they?', 'x = 1 and x = -1', 'x = 0 and x = 3', 'x = sqrt(3) and x = -sqrt(3)', 'x = 3 only', 'x = 1 and x = -1', 'f''(x) = 3x^2 - 3 = 0 gives x^2 = 1, so x = 1 and x = -1 are the critical points.', 890, 'Calculus'),
('What does the second derivative test conclude when f''(c) = 0 and f''''(c) > 0?', 'f has a local minimum at c', 'f has a local maximum at c', 'f has an inflection point at c', 'The test is inconclusive', 'f has a local minimum at c', 'If f''(c) = 0 and f''''(c) > 0, the function is concave up at c, so f has a local minimum there.', 920, 'Calculus'),
('Evaluate lim(x->0) (e^x - 1)/x using L''Hopital''s rule', '1', '0', 'e', 'infinity', '1', 'Both numerator and denominator approach 0; applying L''Hopital''s rule, differentiate both: e^x / 1 -> 1 as x->0.', 950, 'Calculus'),
('What is the Fundamental Theorem of Calculus Part 1?', 'd/dx[integral from a to x of f(t) dt] = f(x)', 'integral from a to b of f(x) dx = F(b) - F(a)', 'f is differentiable implies f is integrable', 'The derivative of a constant is zero', 'd/dx[integral from a to x of f(t) dt] = f(x)', 'FTC Part 1 says differentiating the accumulation function returns the integrand: d/dx[integral_a^x f(t)dt] = f(x).', 860, 'Calculus'),
('Integrate by parts: integral of x*cos(x) dx', 'x*sin(x) + cos(x) + C', 'x*sin(x) - cos(x) + C', '-x*sin(x) + cos(x) + C', 'sin(x) + C', 'x*sin(x) + cos(x) + C', 'Let u=x, dv=cos(x)dx; then du=dx, v=sin(x); IBP gives x*sin(x) - integral of sin(x) dx = x*sin(x) + cos(x) + C.', 1020, 'Calculus'),
('Which convergence test uses lim(n->inf) |a_(n+1)/a_n| to determine series behavior?', 'Ratio test', 'Comparison test', 'Integral test', 'Root test', 'Ratio test', 'The ratio test evaluates L = lim|a_(n+1)/a_n|; the series converges if L < 1 and diverges if L > 1.', 1080, 'Calculus'),
('What is the Maclaurin series for sin(x)?', 'x - x^3/3! + x^5/5! - x^7/7! + ...', '1 - x^2/2! + x^4/4! - ...', '1 + x + x^2/2! + x^3/3! + ...', 'x + x^3/3! + x^5/5! + ...', 'x - x^3/3! + x^5/5! - x^7/7! + ...', 'The Maclaurin series of sin(x) is sum_(n=0)^inf (-1)^n * x^(2n+1)/(2n+1)! = x - x^3/6 + x^5/120 - ..., converging for all x.', 1150, 'Calculus'),
('Find dy/dx by implicit differentiation given x^2 + y^2 = 25', '-x/y', 'x/y', '-y/x', '2x + 2y', '-x/y', 'Differentiating both sides: 2x + 2y*(dy/dx) = 0, so dy/dx = -2x/(2y) = -x/y.', 980, 'Calculus'),
('A ladder 10 ft long slides down a wall. When the bottom is 6 ft from the wall and moving at 2 ft/s, how fast is the top sliding down?', '3/2 ft/s', '2 ft/s', '8/3 ft/s', '1/2 ft/s', '3/2 ft/s', 'By Pythagorean theorem x^2+y^2=100; differentiating: 2x(dx/dt)+2y(dy/dt)=0; at x=6,y=8: 6*2+8*(dy/dt)=0 so dy/dt = -3/2 ft/s (magnitude 3/2).', 1280, 'Calculus'),
('Evaluate the improper integral: integral from 1 to inf of 1/x^2 dx', '1', 'infinity (diverges)', '2', '1/2', '1', 'integral of x^(-2) dx = -x^(-1); evaluating from 1 to inf: lim(b->inf)[-1/b + 1/1] = 0 + 1 = 1.', 1100, 'Calculus'),
('What is the partial derivative with respect to x of f(x,y) = x^2*y + y^3?', '2x*y', '2x*y + 3y^2', 'x^2 + 3y^2', '2x + y^3', '2x*y', 'Treating y as a constant, d/dx[x^2*y + y^3] = 2x*y + 0 = 2x*y.', 1060, 'Calculus'),
('What is the gradient of f(x,y) = x^2 + y^2?', '(2x, 2y)', '(x^2, y^2)', '(2, 2)', '(x, y)', '(2x, 2y)', 'The gradient is the vector of partial derivatives: grad f = (df/dx, df/dy) = (2x, 2y).', 1090, 'Calculus'),
('Does the series sum_(n=1)^inf 1/n^2 converge or diverge?', 'Converges (p-series, p=2>1)', 'Diverges (harmonic-like)', 'Converges only conditionally', 'Diverges by ratio test', 'Converges (p-series, p=2>1)', 'A p-series sum 1/n^p converges when p > 1; here p=2 > 1, so the series converges (to pi^2/6).', 1040, 'Calculus'),
('What substitution simplifies the integral of 1/(x^2 + a^2) dx?', 'x = a*tan(theta)', 'x = a*sin(theta)', 'x = a*sec(theta)', 'x = a*cos(theta)', 'x = a*tan(theta)', 'The substitution x = a*tan(theta) converts x^2+a^2 into a^2*sec^2(theta), simplifying the integral to (1/a)*arctan(x/a) + C.', 1200, 'Calculus'),
('Use partial fractions to decompose 1/((x-1)(x+2)). What is the result?', '(1/3)/(x-1) - (1/3)/(x+2)', '(1/3)/(x-1) + (1/3)/(x+2)', '1/(x-1) - 1/(x+2)', '(1/2)/(x-1) + (1/2)/(x+2)', '(1/3)/(x-1) - (1/3)/(x+2)', 'Setting 1/((x-1)(x+2)) = A/(x-1) + B/(x+2) and solving gives A=1/3, B=-1/3.', 1180, 'Calculus'),
('Which test compares a series sum a_n to a known series sum b_n of similar magnitude?', 'Comparison test', 'Ratio test', 'Root test', 'Alternating series test', 'Comparison test', 'The direct comparison test concludes convergence or divergence of sum a_n by comparing term-by-term with a known series sum b_n.', 970, 'Calculus'),
('Evaluate the Riemann sum limit that defines the definite integral of f(x) on [a,b]', 'lim(n->inf) sum_(i=1)^n f(x_i)*Delta_x where Delta_x = (b-a)/n', 'F(b) - F(a) where F is any function', 'sum_(i=1)^n f(x_i) as n->inf', 'lim(n->inf) f(n)', 'lim(n->inf) sum_(i=1)^n f(x_i)*Delta_x where Delta_x = (b-a)/n', 'The definite integral is defined as the limit of Riemann sums: lim(n->inf) sum f(x_i)*Delta_x, partitioning [a,b] into n subintervals of width Delta_x=(b-a)/n.', 1010, 'Calculus'),
('Evaluate lim(x->inf) (3x^2 + 2x)/(x^2 - 5) by dividing by the highest power', '3', '2', '0', 'infinity', '3', 'Dividing numerator and denominator by x^2 gives (3 + 2/x)/(1 - 5/x^2); as x->inf the terms with 1/x vanish, leaving 3/1 = 3.', 840, 'Calculus'),
('What is the derivative of f(x) = arctan(x)?', '1/(1 + x^2)', 'sqrt(1 - x^2)', '1/sqrt(1 - x^2)', '1/x', '1/(1 + x^2)', 'The derivative of arctan(x) is 1/(1+x^2), derived using implicit differentiation on tan(y)=x.', 900, 'Calculus'),
('Evaluate: integral of e^(2x) dx', 'e^(2x)/2 + C', '2*e^(2x) + C', 'e^(2x) + C', 'e^x/2 + C', 'e^(2x)/2 + C', 'Using substitution u=2x, du=2dx: integral becomes (1/2)*integral of e^u du = e^(2x)/2 + C.', 780, 'Calculus'),
('Find the absolute maximum of f(x) = -x^2 + 4x on [0,3]', '4', '3', '0', '6', '4', 'f''(x) = -2x+4 = 0 gives x=2; f(2)=4, f(0)=0, f(3)=3; the absolute maximum is 4 at x=2.', 1000, 'Calculus'),
('What is the Maclaurin series for cos(x)?', '1 - x^2/2! + x^4/4! - x^6/6! + ...', 'x - x^3/3! + x^5/5! - ...', '1 + x + x^2/2! + x^3/3! + ...', '1 + x^2/2! + x^4/4! + ...', '1 - x^2/2! + x^4/4! - x^6/6! + ...', 'The Maclaurin series of cos(x) is sum_(n=0)^inf (-1)^n * x^(2n)/(2n)! = 1 - x^2/2 + x^4/24 - ..., converging for all x.', 1140, 'Calculus'),
('Apply L''Hopital''s rule to lim(x->0+) x*ln(x). Rewrite as a fraction, then evaluate.', '0', '1', '-1', 'infinity', '0', 'Rewrite x*ln(x) = ln(x)/(1/x); L''Hopital gives (1/x)/(-1/x^2) = -x -> 0 as x->0+.', 1320, 'Calculus'),
('Does the alternating series sum_(n=1)^inf (-1)^n / n converge?', 'Yes, conditionally', 'Yes, absolutely', 'No, it diverges', 'The test is inconclusive', 'Yes, conditionally', 'By the alternating series test, 1/n decreases to 0, so the series converges; but sum 1/n diverges, so it converges only conditionally.', 1130, 'Calculus'),
('If f(x,y) = e^(x*y), what is the mixed partial derivative f_xy?', 'e^(x*y)*(1 + x*y)', 'x*e^(x*y)', 'y*e^(x*y)', 'e^(x*y)', 'e^(x*y)*(1 + x*y)', 'f_x = y*e^(xy); then f_xy = d/dy[y*e^(xy)] = e^(xy) + y*x*e^(xy) = e^(xy)*(1+xy).', 1460, 'Calculus'),
('What is the radius of convergence of sum_(n=0)^inf x^n/n! (the series for e^x)?', 'infinity', '1', 'e', '0', 'infinity', 'Ratio test: lim|x^(n+1)/(n+1)! / (x^n/n!)| = |x|/(n+1) -> 0 for all x, so the radius of convergence is infinity.', 1220, 'Calculus'),
('Evaluate: integral from 0 to pi of sin(x) dx', '2', '0', '1', 'pi', '2', 'The antiderivative of sin(x) is -cos(x); evaluating from 0 to pi: -cos(pi)-(-cos(0)) = 1+1 = 2.', 760, 'Calculus'),
('What condition on a function f guarantees a global minimum on a closed interval [a,b] by the Extreme Value Theorem?', 'f is continuous on [a,b]', 'f is differentiable on [a,b]', 'f is monotone on [a,b]', 'f(a) < f(b)', 'f is continuous on [a,b]', 'The Extreme Value Theorem guarantees that a continuous function on a closed bounded interval attains both a maximum and a minimum.', 870, 'Calculus'),
('Evaluate: integral of 1/(x^2 - 1) dx using partial fractions', '(1/2)*ln|x-1| - (1/2)*ln|x+1| + C', 'ln|x^2-1| + C', '(1/2)*ln|x+1| - (1/2)*ln|x-1| + C', 'arctan(x) + C', '(1/2)*ln|x-1| - (1/2)*ln|x+1| + C', 'Decompose 1/(x^2-1) = (1/2)/(x-1) - (1/2)/(x+1); integrating term by term gives (1/2)ln|x-1| - (1/2)ln|x+1| + C.', 1250, 'Calculus'),
('A box with a square base and open top must hold 32 cm^3. What base length x minimizes surface area?', 'x = 4 cm', 'x = 2 cm', 'x = 8 cm', 'x = 32 cm', 'x = 4 cm', 'Surface area S = x^2 + 4x*h; constraint x^2*h = 32 gives h = 32/x^2; minimizing: dS/dx = 2x - 128/x^2 = 0 yields x^3 = 64, so x = 4.', 1500, 'Calculus'),
('Does the integral from 1 to inf of 1/x dx converge or diverge?', 'Diverges', 'Converges to 1', 'Converges to ln(2)', 'Converges to 2', 'Diverges', 'integral of 1/x dx = ln(x); as x->inf, ln(x)->inf, so the improper integral diverges (harmonic-type divergence).', 1015, 'Calculus'),
('What is the Taylor series of f(x) = 1/(1-x) centered at 0 (for |x| < 1)?', '1 + x + x^2 + x^3 + ...', '1 - x + x^2 - x^3 + ...', 'x + x^2/2 + x^3/3 + ...', '1 + x + x^2/2! + x^3/3! + ...', '1 + x + x^2 + x^3 + ...', 'The geometric series gives 1/(1-x) = sum_(n=0)^inf x^n = 1 + x + x^2 + x^3 + ... for |x| < 1.', 1070, 'Calculus'),
('Using the ratio test, determine convergence of sum_(n=1)^inf n!/2^n', 'Diverges (L = infinity > 1)', 'Converges (L = 1/2 < 1)', 'Converges (L = 0)', 'Inconclusive (L = 1)', 'Diverges (L = infinity > 1)', 'Ratio: |(n+1)!/2^(n+1)| / |n!/2^n| = (n+1)/2 -> infinity as n->inf; since L > 1, the series diverges.', 1380, 'Calculus'),
('Find the interval of convergence of sum_(n=1)^inf (x-2)^n / n', '[1, 3)', '(1, 3)', '[1, 3]', '(-inf, inf)', '[1, 3)', 'Ratio test gives radius R=1 centered at x=2, so x in (1,3); at x=1 the series sum (-1)^n/n converges; at x=3 sum 1/n diverges; IOC is [1,3).', 1750, 'Calculus'),
('Evaluate lim(x->0+) x^x using logarithms and L''Hopital''s rule', '1', '0', 'e', 'infinity', '1', 'Let L = lim x^x; ln L = lim x*ln(x) = lim ln(x)/(1/x); L''Hopital: (1/x)/(-1/x^2) = -x -> 0; so L = e^0 = 1.', 1800, 'Calculus');
